SELECT 
FROM sys_job_api_token
WHERE tenant_id = #{tenantId}
  AND del_flag = 0

    AND caller_name LIKE CONCAT('%', #{callerName}, '%')


    AND status = 'ACTIVE' AND expires_at > #{now}


    AND status = 'REVOKED'


    AND status = 'ACTIVE' AND expires_at <= #{now}

ORDER BY create_time DESC, id DESC

SELECT 
FROM sys_job_api_token
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND del_flag = 0
LIMIT 1

