UPDATE sys_job_api_token
SET last_used_at = #{lastUsedAt},
    update_time = NOW()
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND status = 'ACTIVE'
  AND expires_at > #{lastUsedAt}
  AND del_flag = 0
